package com.bank.transfer.health;

// Mirrors Spring Boot's LivenessState and ReadinessState.
public class AvailabilityState {
    private volatile boolean livenessBroken = false; // set only on unrecoverable internal error
    private volatile boolean warmedUp = false;       // true once pool/cache are ready
    private volatile boolean dbReachable = true;     // simulated dependency
    private volatile boolean refusingTraffic = false; // set during graceful shutdown

    public void markWarmedUp()        { this.warmedUp = true; }
    public void breakLiveness()       { this.livenessBroken = true; }
    public void setDbReachable(boolean v) { this.dbReachable = v; }
    public void refuseTraffic()       { this.refusingTraffic = true; }

    public boolean isLivenessBroken() { return livenessBroken; }
    public boolean isWarmedUp()       { return warmedUp; }
    public boolean isDbReachable()    { return dbReachable; }
    public boolean isRefusingTraffic(){ return refusingTraffic; }
}
