package com.bank.transfer.health;

import java.util.logging.Logger;

// The two probe endpoints. LIVENESS checks ONLY internal state;
// READINESS may also check dependencies and warm-up.
public class HealthEndpoints {
    private static final Logger log = Logger.getLogger(HealthEndpoints.class.getName());
    private final AvailabilityState state;

    public HealthEndpoints(AvailabilityState state) { this.state = state; }

    // GET /actuator/health/liveness
    public boolean liveness() {
        // NEVER check the database here — a DB blip must not restart the fleet.
        boolean up = !state.isLivenessBroken();
        log.fine(() -> "liveness -> " + (up ? "UP" : "DOWN"));
        return up;
    }

    // GET /actuator/health/readiness
    public boolean readiness() {
        // Ready only if warmed up, DB reachable, and not draining.
        boolean up = state.isWarmedUp() && state.isDbReachable() && !state.isRefusingTraffic();
        log.fine(() -> "readiness -> " + (up ? "UP" : "REFUSING_TRAFFIC"));
        return up;
    }
}
