package com.bank.transfer.kube;

import com.bank.transfer.health.HealthEndpoints;
import java.util.logging.Logger;

// Mimics how the kubelet reacts: restart on liveness fail, drain on readiness fail.
public class KubeletSimulator {
    private static final Logger log = Logger.getLogger(KubeletSimulator.class.getName());
    private final HealthEndpoints health;
    private int livenessFailures = 0;
    private boolean inServicePool = false;

    public KubeletSimulator(HealthEndpoints health) { this.health = health; }

    public void poll(String phase) {
        boolean live = health.liveness();
        boolean ready = health.readiness();

        if (!live) {
            livenessFailures++;
            log.warning(() -> phase + ": liveness FAIL (" + livenessFailures + "/3)");
            if (livenessFailures >= 3) log.severe(phase + ": RESTART CONTAINER");
        } else {
            livenessFailures = 0;
        }

        if (ready && !inServicePool) {
            inServicePool = true;
            log.info(phase + ": readiness UP -> ADD to Service pool (traffic flows)");
        } else if (!ready && inServicePool) {
            inServicePool = false;
            log.warning(phase + ": readiness DOWN -> REMOVE from Service pool (no restart)");
        }
    }
}
