package com.bank.transfer;

import com.bank.transfer.health.AvailabilityState;
import com.bank.transfer.health.HealthEndpoints;
import com.bank.transfer.kube.KubeletSimulator;

public class ProbeDemo {
    public static void main(String[] args) {
        AvailabilityState state = new AvailabilityState();
        HealthEndpoints health = new HealthEndpoints(state);
        KubeletSimulator kubelet = new KubeletSimulator(health);

        // Phase 1: cold start — alive but not yet warmed up.
        kubelet.poll("startup");

        // Phase 2: warm-up finishes — pool filled, cache primed.
        state.markWarmedUp();
        kubelet.poll("after-warmup");

        // Phase 3: a 2-second DB blip — readiness drops, liveness STAYS UP.
        state.setDbReachable(false);
        kubelet.poll("db-blip");
        state.setDbReachable(true);
        kubelet.poll("db-recovered");

        // Phase 4: graceful shutdown — refuse traffic first, then exit.
        state.refuseTraffic();
        kubelet.poll("draining");
    }
}
